class menu extends Core { public static $actions = [ 'index' => self::ROLE_EDITOR, ]; public static $menuTree = []; public static $menuHtml = ''; public static $orphans = []; public function index() { $lang = isset($_GET['l']) ? $_GET['l'] : null; if ( $lang && $lang != self::$siteContent && array_key_exists($lang, self::$languages) === true && is_dir(self::DATA_DIR . $lang) ) { $_SESSION['ZWII_SITE_CONTENT'] = $lang; header('Refresh:0; url=' . Helper::baseUrl() . $this->getUrl()); exit(); } if ($this->getUser('permission', 'page', 'edit') !== true) { $this->addOutput([ 'access' => false ]); return; } if ($this->isPost()) { $raw = $this->getInput('menuEditOrder', Helper::FILTER_STRING_LONG); $order = json_decode(html_entity_decode($raw, ENT_QUOTES | ENT_HTML5, 'UTF-8'), true); if (is_array($order)) { foreach ($order as $item) { $pageId = isset($item['id']) ? (string) $item['id'] : null; $parentId = isset($item['parent']) ? (string) $item['parent'] : ''; $position = isset($item['position']) ? (int) $item['position'] : 0; if ( $pageId === null || $this->getData(['page', $pageId]) === null || $this->getData(['page', $pageId, 'block']) === 'bar' ) { continue; } if ( $parentId !== '' && ( $this->getData(['page', $parentId]) === null || $this->getData(['page', $parentId, 'block']) === 'bar' ) ) { continue; } $this->setData(['page', $pageId, 'parentPageId', $parentId], false); $this->setData(['page', $pageId, 'position', $position], false); } $this->saveDB('page'); } $this->addOutput([ 'redirect' => Helper::baseUrl() . 'menu', 'notification' => Helper::translate('Modifications enregistrées'), 'state' => true ]); return; } $allPages = $this->getData(['page']); if (!is_array($allPages)) { $allPages = []; } $menuPages = []; $orphanPages = []; foreach ($allPages as $pageId => $pageData) { if (isset($pageData['block']) && $pageData['block'] === 'bar') { continue; } if (isset($pageData['extraPosition']) && $pageData['extraPosition'] === true) { continue; } $position = isset($pageData['position']) ? (int) $pageData['position'] : 0; if ($position === 0) { $orphanPages[$pageId] = $pageData; } else { $menuPages[$pageId] = $pageData; } } uasort($menuPages, function ($a, $b) { return (int) $a['position'] - (int) $b['position']; }); self::$menuTree = $this->buildMenuTree($menuPages); self::$orphans = $orphanPages; self::$menuHtml = ''; foreach (self::$menuTree as $node) { self::$menuHtml .= "\n" . $this->renderMenuNode($node); } $this->addOutput([ 'title' => Helper::translate('Structure du site'), 'view' => 'index', 'vendor' => ['sortablejs'], 'showBarEditButton' => false, ]); } private function renderMenuNode(array $node, int $depth = 0): string { $indent = str_repeat('  ', $depth); $html = $indent . '<li class="menuEditItem" data-id="' . htmlspecialchars($node['id'], ENT_QUOTES) . '" data-depth="' . $depth . '">'; $html .= '<div class="menuEditItemRow">'; $html .= '<span class="menuEditHandle zwiico-menu"></span>'; $html .= '<span class="menuEditTitle">' . $node['title'] . '</span>'; $html .= '<small class="menuEditId">(' . htmlspecialchars($node['id'], ENT_QUOTES) . ')</small>'; $html .= '</div>'; $html .= "\n" . $indent . '  <ul class="menuEditNested sortableList">'; foreach ($node['children'] as $child) { $html .= "\n" . $this->renderMenuNode($child, $depth + 1); } $html .= "\n" . $indent . '  </ul>'; $html .= "\n" . $indent . '</li>'; return $html; } private function buildMenuTree(array $pages): array { $tree = []; $children = []; foreach ($pages as $pageId => $pageData) { $parentId = isset($pageData['parentPageId']) ? $pageData['parentPageId'] : ''; $children[$parentId][] = $pageId; } if (isset($children[''])) { foreach ($children[''] as $rootId) { $tree[] = $this->buildNode($rootId, $pages, $children); } } return $tree; } private function buildNode(string $pageId, array $pages, array $children): array { $node = [ 'id' => $pageId, 'title' => isset($pages[$pageId]['title']) ? $pages[$pageId]['title'] : $pageId, 'position' => isset($pages[$pageId]['position']) ? (int) $pages[$pageId]['position'] : 0, 'children' => [], ]; if (isset($children[$pageId])) { $childIds = $children[$pageId]; usort($childIds, function ($a, $b) use ($pages) { $pa = isset($pages[$a]['position']) ? (int) $pages[$a]['position'] : 0; $pb = isset($pages[$b]['position']) ? (int) $pages[$b]['position'] : 0; return $pa - $pb; }); foreach ($childIds as $childId) { $node['children'][] = $this->buildNode($childId, $pages, $children); } } return $node; } }
